{
  "name": "opencode-reasoning-effort-guard",
  "version": "0.1.2",
  "description": "Keep OpenCode from sending a reasoning effort the provider rejects.",
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "reasoning",
    "reasoning-effort"
  ],
  "license": "MIT",
  "author": "Meer Estiyak",
  "homepage": "https://github.com/mmestiyak/opencode-reasoning-effort-guard#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mmestiyak/opencode-reasoning-effort-guard.git"
  },
  "bugs": "https://github.com/mmestiyak/opencode-reasoning-effort-guard/issues",
  "scripts": {
    "test": "vitest run",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.30"
  },
  "devDependencies": {
    "@types/node": "^26.6.5",
    "typescript": "^7.0.2",
    "vitest": "^4.1.12"
  }
}
